body { margin: 0; font-family: 'Open Sans','Inter','Segoe UI',Arial,sans-serif; background: transparent; color: #e2e8f0; }
.cards { display: flex; flex-direction: column; gap: 18px; padding: 4px; }
.card { border: 1px solid #334155; border-radius: 6px; overflow: hidden; background: #1E293B; }
.card-header { display: flex; justify-content: space-between; align-items: center; background: #1E293B; color: #ffffff; padding: 10px 16px; font-weight: 700; font-size: 14px; border-bottom: 1px solid #334155; }
.card-header .title { flex: 1; }
.card-header .total { font-size: 16px; }
.card-body { background: #1E293B; color: #e2e8f0; }
.card-body table { width: 100%; border-collapse: collapse; font-size: 13px; table-layout: fixed; }
.card-body th, .card-body td { padding: 8px 12px; text-align: left; overflow: hidden; text-overflow: ellipsis; }
.card-body th:nth-child(1), .card-body td:nth-child(1) { width: 52%; }
.card-body th:nth-child(2), .card-body td:nth-child(2) { width: 18%; }
.card-body th:nth-child(3), .card-body td:nth-child(3) { width: 15%; }
.card-body th:nth-child(4), .card-body td:nth-child(4) { width: 15%; }
.card-body td.num, .card-body th.num { text-align: right; font-variant-numeric: tabular-nums; }
.card-scroll { max-height: 280px; overflow-y: auto; }
.card-scroll::-webkit-scrollbar { width: 8px; }
.card-scroll::-webkit-scrollbar-track { background: #0f172a; }
.card-scroll::-webkit-scrollbar-thumb { background: #334155; border-radius: 4px; }
.card-scroll::-webkit-scrollbar-thumb:hover { background: #475569; }
.card-scroll thead th { position: sticky; top: 0; background: #0f172a; color: #cbd5e1; font-weight: 700; font-size: 12px; text-transform: uppercase; letter-spacing: 0.04em; border-bottom: 1px solid #334155; z-index: 1; }
.card-scroll tr.line { border-bottom: 1px solid #334155; }
.card-scroll tr.line:nth-child(even) td { background: #0f172a; }
.card-scroll tr.line td { color: #e2e8f0; }
.card-summary { border-top: 1px solid #334155; background: #0f172a; }
.card-summary tr.summary { font-weight: 700; color: #ffffff; }
.card-summary tr.summary td { border-top: 1px solid #334155; }
.card-summary tr.summary:first-child td { border-top: none; }
.card-body .err { padding: 12px 16px; color: #fca5a5; background: rgba(127,29,29,0.4); font-size: 13px; }
.toolbar { display: flex; justify-content: flex-end; padding: 0 4px 8px 4px; }
.toggle-all-btn { background: transparent; border: 1px solid #86efac; color: #86efac; padding: 5px; border-radius: 4px; cursor: pointer; display: inline-flex; align-items: center; justify-content: center; line-height: 0; }
.toggle-all-btn:hover { background: rgba(134,239,172,0.12); color: #86efac; border-color: #86efac; }
.toggle-all-btn svg { width: 14px; height: 14px; flex: none; }
.card-header { cursor: pointer; user-select: none; }
.card-header .chevron { width: 16px; height: 16px; margin-left: 12px; transition: transform 0.15s ease; flex: none; color: #cbd5e1; }
.card-header:hover .chevron { color: #ffffff; }
.card.collapsed .card-header { border-bottom: none; }
.card.collapsed .card-header .chevron { transform: rotate(-90deg); }
.card.collapsed .card-body { display: none; }

