function fmt(n) {
  if (n == null || isNaN(n)) return '';
  const v = Number(n);
  return (v < 0 ? '-' : '') + '$' + Math.abs(v).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

function fmtRate(r) {
  if (r == null || r === '') return '';
  const v = Number(r);
  if (isNaN(v)) return String(r);
  return (v < 0 ? '-' : '') + '$' + Math.abs(v).toFixed(4);
}

function fmtQty(q, unit) {
  if (q == null || q === '') return '';
  const n = Number(q);
  if (isNaN(n)) return String(q);
  const s = n.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return unit ? `${s} ${unit}` : s;
}

function escapeHtml(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const collapsedSet = new Set();
let _modelCache = null;

const CHEVRON_SVG = '<svg class="chevron" viewBox="0 0 16 16" fill="currentColor"><path d="M4 6l4 4 4-4z"/></svg>';
const COLLAPSE_ALL_SVG = '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6l5-3 5 3"/><path d="M3 10l5 3 5-3"/></svg>';
const EXPAND_ALL_SVG = '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M3 3l5 3 5-3"/><path d="M3 13l5-3 5 3"/></svg>';

function renderCard(b) {
  const mtid = String(b.masterTariffId == null ? '' : b.masterTariffId);
  const isCollapsed = collapsedSet.has(mtid);
  const title = `${escapeHtml(b.lseName || '')} | ${escapeHtml(b.tariffName || '')} | ${escapeHtml(b.serviceType || '')}`;
  const total = fmt(b.adjustedTotalCost);
  let body;
  if (b.error) {
    body = `<div class="err">Calculate failed: ${escapeHtml(b.error)}</div>`;
  } else {
    const lineRows = (b.lines || []).map(l => `
      <tr class="line">
        <td>${escapeHtml(l.name)}</td>
        <td class="num">${escapeHtml(fmtQty(l.qty, l.qty_unit))}</td>
        <td class="num">${escapeHtml(fmtRate(l.rate))}</td>
        <td class="num">${escapeHtml(fmt(l.cost))}</td>
      </tr>`).join('');
    body = `
      <div class="card-scroll">
        <table>
          <thead><tr>
            <th>Charge</th><th class="num">QTY</th><th class="num">Rate</th><th class="num">Cost</th>
          </tr></thead>
          <tbody>${lineRows}</tbody>
        </table>
      </div>
      <div class="card-summary">
        <table>
          <tbody>
            <tr class="summary"><td colspan="3">Sub Total Cost</td><td class="num">${fmt(b.subTotalCost)}</td></tr>
            <tr class="summary"><td colspan="3">Non Bypassable Cost</td><td class="num">${fmt(b.nonBypassableCost)}</td></tr>
            <tr class="summary"><td colspan="3">Tax Cost</td><td class="num">${fmt(b.taxCost)}</td></tr>
          </tbody>
        </table>
      </div>`;
  }
  return `
    <div class="card ${isCollapsed ? 'collapsed' : ''}">
      <div class="card-header" data-toggle-mtid="${escapeHtml(mtid)}">
        <div class="title">${title}</div>
        <div class="total">${total}</div>
        ${CHEVRON_SVG}
      </div>
      <div class="card-body">${body}</div>
    </div>`;
}

function allCollapsed(blocks) {
  return blocks.length > 0 && blocks.every(b => collapsedSet.has(String(b.masterTariffId == null ? '' : b.masterTariffId)));
}

function render(model) {
  _modelCache = model;
  const blocks = Array.isArray(model && model.blocks) ? model.blocks : [];
  const root = document.getElementById('root');
  if (!root) return;
  if (!blocks.length) {
    root.innerHTML = '<div style="padding:16px;color:#94a3b8;font-size:13px">No results yet. Pick tariffs and click Calculate.</div>';
    return;
  }
  const allCol = allCollapsed(blocks);
  const toolbar = `
    <div class="toolbar">
      <button class="toggle-all-btn" data-toggle-all="${allCol ? 'expand' : 'collapse'}" title="${allCol ? 'Expand all' : 'Collapse all'}" aria-label="${allCol ? 'Expand all' : 'Collapse all'}">
        ${allCol ? EXPAND_ALL_SVG : COLLAPSE_ALL_SVG}
      </button>
    </div>`;
  root.innerHTML = toolbar + '<div class="cards">' + blocks.map(renderCard).join('') + '</div>';
}

function onRootClick(e) {
  const allBtn = e.target.closest('.toggle-all-btn');
  if (allBtn) {
    const action = allBtn.dataset.toggleAll;
    const blocks = Array.isArray(_modelCache && _modelCache.blocks) ? _modelCache.blocks : [];
    if (action === 'expand') {
      collapsedSet.clear();
    } else {
      blocks.forEach(b => collapsedSet.add(String(b.masterTariffId == null ? '' : b.masterTariffId)));
    }
    render(_modelCache);
    return;
  }
  const header = e.target.closest('.card-header[data-toggle-mtid]');
  if (header) {
    const mtid = header.dataset.toggleMtid;
    if (collapsedSet.has(mtid)) collapsedSet.delete(mtid);
    else collapsedSet.add(mtid);
    render(_modelCache);
  }
}

appsmith.onReady(() => {
  render(appsmith.model);
  appsmith.onModelChange(render);
  document.addEventListener('click', onRootClick);
});

